import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Link,
  Text,
  Section,
  Row,
  Column,
  Img,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type HeaderWithLogoVariant = "minimal" | "with-text";

export type HeaderWithLogoAlignment = "left" | "center" | "right";

export interface HeaderWithLogoProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  text?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  textColor?: string;
  variant?: HeaderWithLogoVariant;
  alignment?: HeaderWithLogoAlignment;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = [
  "@media only screen and (max-width: 599px) {",
  "  .header-logo-text-stack { display: block !important; width: 100% !important; }",
  "  .header-logo-text-left-logo { padding-bottom: 24px !important; }",
  "  .header-logo-text-right-row { display: table !important; width: 100% !important; }",
  "  .header-logo-text-right-copy-cell { display: table-footer-group !important; width: 100% !important; }",
  "  .header-logo-text-right-logo { display: table-header-group !important; text-align: right !important; width: 100% !important; }",
  "  .header-logo-text-right-copy { padding-top: 24px !important; text-align: right !important; }",
  "}",
].join("\n");

const defaults = {
  backgroundColor: "#fffffe",
  logoAlt: "Maizzle",
  logoHref: "https://example.com",
  logoSrc: emailAsset("maizzle-insignia.png"),
  pageBackgroundColor: "#f1f5f9",
  text: "Medium, rare, but mostly well-done\nHTML email components.",
  textColor: "#030712",
};

type SectionProps = Omit<HeaderWithLogoProps, "theme">;

type ResolvedProps = typeof defaults & SectionProps;

const Logo = ({ props }: { props: ResolvedProps }) => (
  <Link href={props.logoHref}>
    <Img
      alt={props.logoAlt}
      src={props.logoSrc}
      style={{ maxWidth: "100%", verticalAlign: "middle" }}
      width={55}
    />
  </Link>
);

const Copy = ({
  centered = false,
  props,
}: {
  centered?: boolean;
  props: ResolvedProps;
}) => (
  <Text
    style={{
      color: props.textColor,
      fontFamily,
      fontSize: "16px",
      fontWeight: 500,
      lineHeight: "24px",
      margin: 0,
      textAlign: centered ? "center" : undefined,
    }}
  >
    {(() => {
      if (centered) {
        return props.text.split("\n").map((line, index) => (
          <Fragment key={line}>
            {index > 0 ? <br /> : null}
            {line}
          </Fragment>
        ));
      }
      return props.text.replaceAll("\n", " ");
    })()}
  </Text>
);

const WithText = ({
  alignment,
  props,
}: {
  alignment: HeaderWithLogoAlignment;
  props: ResolvedProps;
}) => {
  if (alignment === "center") {
    return (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column>
              <Section style={{ textAlign: "center" }}>
                <Logo props={props} />
              </Section>
              <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
              <Copy centered props={props} />
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  if (alignment === "right") {
    return (
      <Section className="header-logo-text-right-row" width="100%">
        <Fragment>
          <Row>
            <Column
              className="header-logo-text-right-copy-cell"
              style={{ width: "50%" }}
            >
              <Section className="header-logo-text-right-copy">
                <Copy props={props} />
              </Section>
            </Column>
            <Column
              className="header-logo-text-right-logo"
              style={{ textAlign: "right", width: "50%" }}
            >
              <Logo props={props} />
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  return (
    <Section width="100%">
      <Fragment>
        <Row>
          <Column
            className="header-logo-text-stack header-logo-text-left-logo"
            style={{ width: "50%" }}
          >
            <Logo props={props} />
          </Column>
          <Column className="header-logo-text-stack" style={{ width: "50%" }}>
            <Copy props={props} />
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogoSection = (props: SectionProps) => {
  const alignment = props.alignment ?? "center";
  const variant = props.variant ?? "minimal";
  const resolved = { ...defaults, ...props } as ResolvedProps;
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column style={{ maxWidth: "100%", width: "600px" }}>
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    style={{
                      backgroundColor: resolved.backgroundColor,
                      padding: "24px",
                      textAlign: variant === "minimal" ? alignment : undefined,
                    }}
                  >
                    {variant === "minimal" ? (
                      <Logo props={resolved} />
                    ) : (
                      <WithText alignment={alignment} props={resolved} />
                    )}
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogo = ({
  alignment = "center",
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "minimal",
  ...props
}: HeaderWithLogoProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: responsiveStyles }} />
    </EmailHead>
    <Preview>Medium, rare, but mostly well-done HTML email components.</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <HeaderWithLogoSection
          {...props}
          alignment={alignment}
          pageBackgroundColor={pageBackgroundColor}
          variant={variant}
        />
      </Body>
    </EmailTailwind>
  </Html>
);

HeaderWithLogo.PreviewProps = {
  alignment: "center",
  theme: defaultTheme,
  variant: "minimal",
} satisfies HeaderWithLogoProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
